          "FTC’s business information protection guide provides context for proportionate retention and limited access. Handling a comment does not mean copying private orders, contact details and entire chats into a marketing workbook. Connect support work through a necessary summary and reference, giving appropriate material to the person who can resolve it while others receive status.\n\nWhere a private route is needed, provide a confirmed brand destination rather than asking someone to post payment information publicly. The creator should know which cases to route and which can be addressed on the original piece. A response-speed target should not reward acting beyond authority. Accuracy, appropriate access and a transferable state need to coexist in the design. The team should therefore distinguish an acknowledgment from a substantive answer and a resolved case. Those states can have different owners without requiring everyone to view the sensitive detail behind the resolution."
