          "Meta’s DM feature explanation introduced controls including read receipts in its 2024 announcement. A read indication cannot establish agreement, and its absence does not establish deliberate disregard. Keep a technical messaging state separate from a commercial task state. Actual commitments need explicit expression and appropriate confirmation.\n\nA response record can distinguish seen, accepted by an owner, awaiting facts, answered and resolved. The last two are not identical either; a support answer may merely communicate the next step. Give unfinished work an owner and review date instead of using reply volume to declare everything closed. This avoids unnecessary pressure on creators while locating work waiting inside the brand. It also supports a realistic handover at the end of a campaign: a new team member can see which questions still require action rather than infer completion from a thread that contains several friendly acknowledgments."
