          "Some advice concerns a creator’s ongoing management of their own account, while a brand may be purchasing a single production asset. Use the creator brief to check who publishes, whom viewers are invited to follow and who maintains subsequent content. One person’s long-term practice should not silently become a short-term acceptance condition for a different account. The same recommendation can be useful background and still be unsuitable as the requirement in this particular purchase."
