          "A statement such as more Reels help follower growth may combine three claims: the platform offers more production tools, an author observed growth, or any brand can reproduce a result. These need different evidence. Rewrite them as separate, checkable propositions rather than accepting every implication because the sentence reads smoothly.\n\nRecord original wording, date, author and intended users. An unsourced screenshot is a lead to investigate rather than a creator procurement requirement. In particular, do not make a creator guarantee a percentage from someone else’s short post. A brand can commission work and defined tasks without converting unverified older advice into an unconditional outcome obligation. This first step often reveals that the useful part of a recommendation is an explanation problem or production habit, while the growth promise attached to it has no suitable basis for the current assignment."
