          "Meta’s unconnected recommendation explanation describes content shown outside a person’s following network. This supports the distinction between viewing and following without establishing the route of a particular view or attributing this campaign’s growth. High views should not be renamed high new-follower retention.\n\nPreserve available fields, sources and periods, explaining whether they distinguish net movement, following events or later viewing. Do not invent a cohort where they do not. The brand can use observations to adjust an explanation or profile while keeping editorial judgment separate from proven growth causes. Where information is incomplete, a narrower conclusion is more useful than a precise but incorrect ratio. The same limitation should remain visible when the report is shortened for another team, especially if the recommendation originally came from a dated article that already used a different metric."
