          "For each task, retain a common name, technical name, question phrasing and terms that may be confused with it. Explain whether they are true synonyms or refer to different products or conditions. Ask someone familiar with the actual operation to check them. A larger result count does not prove semantic accuracy.\n\nFor multilingual projects, preserve real phrasing in each language rather than declaring a literal translation locally standard. Record whether a term came from customer questions, product material or creator work. Without actual collection, label it an editorial candidate for validation. The map supports research and communication, not a requirement to force every term into every caption. It can also reveal a necessary exclusion: if a term commonly refers to a product feature this model does not have, the brief should make that limitation clear rather than exploiting the term’s popularity."
