          "Combine topic and task terms, adding language or location clues where appropriate. Preserve the exact query, date, account context and filters actually available. Do not enter result positions for searches never performed or describe one person’s displayed order as a universal ranking.\n\nMeta’s content ranking explanation provides context for personalization and user choices affecting presentation. It is not a fixed weight table for a particular Instagram search term. The record should explain what the researcher saw and did not verify rather than announce a new ranking rule on the platform’s behalf. A colleague reproducing the query may see different results, which does not by itself establish an error or manipulation. What needs to remain reproducible is the research procedure and selection reasoning, with observed outputs tied to the session in which they actually appeared."
