          "A topic in a candidate biography is a research starting point. Open relevant work and examine the actual question, visible demonstration conditions and distinction between personal experience and general conclusions. Preserve source links and review dates. Reposted work is not automatically production completed by the account owner.\n\nBefore outreach, confirm account, author and public contact route. Similar names do not establish the same person, and keyword presence does not prove professional credentials. The brand is selecting capability and terms appropriate to the assignment, not whichever profile is best at listing popular vocabulary. Where necessary evidence is missing, keep it unresolved rather than upgrading a candidate to verified expert. This distinction is especially useful for complex demonstrations: a short clip may show an interesting result but leave the underlying procedure or creator’s role unclear. Research should identify that gap before procurement assumes the person can reproduce the work."
