          "Meta’s unconnected recommendation explanation describes content and interest understanding in recommendation systems. It does not establish that a word produced this project’s views or that replacing it would yield a particular change. Viewing, search discovery and following should be discussed separately according to available evidence.\n\nWithout the necessary source breakdown, total views cannot reveal how much came from search. Relevant questions or an editorial judgment after clearer topic wording may still be recorded, but should not be called proven search-optimization results. Avoid crediting every performance difference to a caption or making creators responsible for an attribution claim without evidence. This preserves room for useful learning: the team can improve how it describes a product even when the platform does not expose a field that would support a precise search contribution. The limitation belongs beside the conclusion rather than only in a general methodology appendix."
