          "Preserve audience question, vocabulary provenance, query record, candidate evidence and final topic. State what was actually searched and which items remain suggestions for validation. Without a live ranking study, do not claim complete search-opportunity coverage in the handoff.\n\nInstagram SEO can reasonably help a brand organize and clarify relevant content and creator research. It should serve genuine explanation, accurate matching and specific outreach rather than turn influencer marketing into keyword accumulation. A natural title, work that answers its question and evidence supporting the next action give this exercise a useful role. The final brief should make sense to the creator even without the search spreadsheet. If it only contains a target term and a promise of traffic, the brand has not yet supplied the audience task or factual boundaries needed to commission responsible work."
