          "Before research, state market, language, local date and time zone. Content trending at headquarters may not fit the event’s region, and a morning observation is not an all-day conclusion. For a same-day decision, agree on a check point and receiving owner rather than using real-time as an adjective without a timestamp.\n\nPut the audience task in the creator brief: event participation, product explanation or a professional question. A trend is a possible expression route, not a reason to replace the intended audience. Decline where no suitable connection exists. That does not establish a brand is behind; it prevents assigning creator time and budget to work that cannot support the task. State the reason before viewing examples where possible, so an entertaining discovery does not quietly become the project’s objective simply because the team likes the format."
