          "最终记录地区、时间、来源、样本、相关性、权限状态、可行性和决定。可以继续、改成原创方向、等待资料或不参加。只说“很火，快拍”不能让创作者负责任地执行，也不能让品牌判断是否值得采购。\n\nTikTok 当天趋势研究应服务达人营销的真实任务。它帮助品牌找到适合的表达与创作伙伴，同时保留事实与使用条件。今天有价值的选择，不一定是参加最热的声音，而是能说明为何与目标观众有关、谁能真实制作以及下一步如何确认的合作安排。未确认的条件应交给实际负责人，不应从最终决定里消失。",
          "The final note should preserve region, time, source, samples, relevance, permission state, feasibility and decision. Continue, redesign as original work, await evidence or decline. Very popular, film quickly gives neither the creator a responsible assignment nor the brand a basis for purchase.\n\nSame-day TikTok research should serve an actual creator-marketing task. It helps find suitable expression and collaborators while retaining facts and use conditions. The valuable choice today is not necessarily the hottest sound. It is a collaboration whose owner can explain relevance to the intended audience, genuine production capability and the next confirmation step. Keep that note with the brief so a later reviewer can distinguish the observed trend from the brand’s own adaptation and can see which limitations still applied when the work was commissioned. Assign every unresolved condition to an actual owner rather than letting it disappear from the final decision."
