          "Views, likes, comments and shares supply different clues and are not interchangeable. Preserve original field names, time and source for values actually available; explain what was not obtained. Interpret comment content by its question rather than automatically counting an inquiry as purchase intent.\n\nInstagram’s creator education explanation provides background for account-level performance guidance, not the current project’s data. A commercial-event question needs suitable business records rather than revenue reverse-engineered from trial interaction. Separate an editorial judgment that the explanation is clearer from a causal claim of increased sales so the brand can decide what further evidence is needed. A concise report should retain this separation. A larger sharing total might justify examining how people pass along the content, while still leaving both comprehension and commercial contribution unresolved."
