          "结束时保存问题、版本、许可、设置确认、观察窗口、字段、限制和决定。让接收人能分辨真实测试、假设演练与编辑建议。没有随机分组或业务证据，就不要在摘要里称已证明提升转化。\n\nTrial Reels 在达人营销中的合理用途，是支持小范围创意学习。它不能替品牌补出缺失的事实、替创作者承诺观众反应，或替团队完成私密审片。把问题限定清楚，让发布范围、工作与结论保持一致，才有条件把试发经验用于下一次合作。",
          "Preserve question, versions, permissions, setting confirmation, observation period, fields, limits and decision. A recipient should distinguish actual testing, hypothetical rehearsal and editorial advice. Without random assignment or commercial evidence, do not summarize the exercise as proven conversion improvement.\n\nTrial Reels can support scoped creative learning in influencer marketing. They cannot supply missing product facts, promise audience reaction for a creator or replace private review. A bounded question and consistency between publication scope, work and conclusions make the experience useful for the next partnership. The final record should let another owner explain both the creative choice and the remaining uncertainty. If it contains only a larger number beside one file name, the team has not yet preserved the context needed to reuse that choice responsibly."
