          "Separate factual or safety issues, failure to meet original scope and new preferences or assignments. This is a handling recommendation, not a verdict on an actual dispute. Describe the specific concern and evidence before an authorized owner decides to pause, correct or defer.\n\nA scheduled record does not require publishing a real error. Conversely, a new preference does not automatically make the original defective. Where refilming, extended review or a changed publication time is needed, explain cost, timing and creator availability.\n\nHave one identified receiver communicate the decision rather than letting different brand colleagues demand both retention and removal of the same scene. Until a conflict is resolved, do not ask the operator to guess between incompatible instructions. Record which decision replaced which earlier approval so a later person does not revive an obsolete version while attempting to help."
