          "After the account owner saves the appropriate website address in the current profile editor, return to the public profile and test as a visitor. Labels and availability vary; a historical screenshot does not replace current confirmation. Check displayed text, destination and unnecessary intermediate steps.\n\nAt minimum inspect mobile reading, the primary action and forms, including access outside an editor where relevant. A page visible to a logged-in brand colleague may not be visible in the same way to the audience.\n\nTesting does not require real customer information. Use an authorized test method and let the receiver distinguish tests from actual requests. Preserve observation time and problems rather than upgrading one successful test to permanent availability. If the page opens but the intended action fails, setup is not ready for the invitation even though the profile technically contains a link."
