          "Meta’s recommendation eligibility explanation distinguishes permitted content from recommendation eligibility. It supplies platform context, not a diagnosis of this account or certification of brand fit. Do not infer wrongdoing from a single distribution decline or treat recommendation eligibility as a reason the brand must partner.\n\nThe brand still evaluates work, product facts, applicable market and scope. Let account owners verify relevant status instead of having outside researchers replace it with public screenshots.\n\nA decision to decline can rest on task mismatch without inventing a safety or authenticity accusation to make it sound stronger. This keeps research proportionate: the team needs enough evidence for the purchasing decision, not an unnecessary verdict on the creator’s entire account. It can preserve a suitable contact for another project even when the present assignment is a poor match."
