          "完成时交出观众任务、能力证据、适当受众资料、范围、接收条件与未知。规模有作用时说明作用，没有足够证据时继续研究或选择其他合作方式。不要把一个公开数字变成对全部商业能力的判断。\n\n大 Instagram 关注量可以带来值得研究的机会，但它不替代作品与任务匹配，也不构成怀疑个人的理由。品牌围绕真实工作选择创作者，才能既重视传播能力，又保持证据和合作条件清楚。\n\n最终决定应该能被另一个同事解释，而不是只展示一个更大的总数。",
          "Hand over audience task, capability evidence, appropriate audience information, scope, receiving conditions and unknowns. Explain scale’s role where relevant, and continue research or choose another collaboration form where evidence is insufficient. A public number should not become a judgment on every commercial capability.\n\nA large Instagram following can identify an opportunity worth studying. It replaces neither work-to-task matching nor a basis for accusing an individual. Selecting around actual assignments allows a brand to value distribution while keeping evidence and terms clear.\n\nAnother colleague should be able to explain the final choice rather than merely display the larger total. That is the test of whether scale has supported the partnership decision or quietly substituted for it."
