          "Colleagues may recognize one name while disagreeing about the purchase. One wants event hosting, another account publication and a third wants a familiar clip in advertising. These are different jobs and permissions, not one generic collaboration.\n\nUse the creator brief to define intended audience, question, role, deliverables, market and timing. A well-known creator’s representative team does not complete the brand’s requirements for it.\n\nClear scope also helps decide whether the assignment needs that person, their production team or another capable collaborator. Name recognition does not establish suitability for every production task. Before outreach, the receiving owner should be able to state what would count as a useful response: interest in one defined role, clarification of representation or a quotation for particular work. Otherwise even a prompt reply may leave the actual purchasing decision unresolved."
