          "Distinguish performance, actual experience, professional explanation and production contribution. A person appearing in a video may not have produced everything. Familiarity with a face does not establish whether the work was independent, a guest appearance or commissioned by a brand. Preserve source and confirmed elements.\n\nFor new work, examine evidence of relevant capability. For existing footage, focus on rights and intended use. Those require different outreach questions rather than one vague email.\n\nThe candidate research method connects a specific question with work evidence. The brand need not judge a whole career; it needs to explain why a particular public piece warrants discussion. This also helps a representative route the request. A licensing inquiry can go to the appropriate rights owner, while a new production brief can identify the person responsible for considering a fresh assignment."
