      [
        [
          "健康主张不能由外形证明",
          "Appearance does not substantiate a health claim"
        ],
        [
          "FTC 的健康产品广告指南针对美国相关广告讨论明示、暗示主张与证据要求。它提醒品牌审核画面与语言整体传达什么，不能让健身形象替代产品健康效果的支持。其他地区仍按适用要求处理。\n\n服装或器材展示不应被剪成未经支持的减重、治疗或身体变化保证。个人经验也不自动成为所有人的结果。需要具体健康主张时交给有相应责任的专业审核，而不是要求模特凭出镜承担证明。\n\n本文提供内容任务边界，不做个体健康判断，也不以某种外观推断健康状态。",
          "FTC’s health-product advertising guidance discusses express and implied claims and substantiation for U.S.-relevant advertising. Review what image and language communicate together rather than using a fitness appearance as support for product health benefits. Applicable requirements elsewhere still need assessment.\n\nA clothing or equipment demonstration should not be edited into unsupported weight-loss, treatment or transformation guarantees. Personal experience is not automatically everyone’s outcome. Route specific health claims to appropriately responsible review instead of asking the model to substantiate them merely by appearing.\n\nThis article defines a content assignment and makes no individual health assessment or inference of health from appearance. A useful production note can identify prohibited implications as well as approved words, so a technically unchanged shot does not acquire a different claim through added copy, sequencing or surrounding advertising context."
        ],
        [
          "ftcHealth"
        ]
      ],
      [
        [
          "分别约定发布与素材使用",
          "Agree publication and asset use separately"
        ],
        [
          "美国版权局的作品使用问答提供美国范围的许可背景。收到图片不等于品牌可以无限期投放、交给第三方修改或使用出镜人的账号身份。作品、人物同意、音乐和其他元素的范围，应由合适人员按实际用途核对。\n\n用作品与许可范围记录渠道、地区、期限、版本与编辑条件。账号发布与品牌渠道使用分别说明，不把制作费等同于所有未来权利。\n\n需要复用时保留批准的上下文与限定条件。裁切或改文案可能改变含义，应明确哪些变化可以直接执行，哪些需要重新确认。",
          "U.S. Copyright Office’s work-use FAQ supplies U.S.-specific permission context. Receiving images does not establish unlimited advertising, third-party adaptation or use of the performer’s account identity. Appropriate owners should check work, personal consent, music and other elements against actual use.\n\nRecord channel, market, duration, version and editing conditions through the work and usage scope. Separate account publication from brand-channel use, rather than equating a production fee with every future right.\n\nPreserve approved context and qualifications when reusing work. A crop or caption can change meaning, so identify changes within scope and those needing confirmation again. The handoff should make it possible for a media operator to locate a usable approved variant without guessing whether a similar file carries the same permissions or preserves the same product claim."
        ],
        [
          "usCopyright"
        ]
      ],
      [
        [
          "商业合作不等于真实体验已经发生",
          "A commercial arrangement does not establish actual experience"
        ],
        [
          "Meta 的创作者合作说明提供账号合作与放大的平台背景，但不证明本次出镜人实际长期使用产品，也不授予具体品牌权限。品牌应分清模特演示、个人体验与合作广告的实际安排。\n\n拍摄一个穿着场景，可以只说明这次展示；不能未经事实支持改成“我一直推荐”。需要真实个人意见时，让创作者决定自己能够如实表达什么，并确认适用商业说明。\n\n品牌也不应因为对方不愿说某句经历，就认定其制作表现不合格。范围与真实性需要一起讨论。",
          "Meta’s creator collaboration explanation supplies context for account partnerships and amplification. It does not establish long-term personal use by this performer or grant a particular brand permission. Distinguish a model demonstration, personal experience and actual advertising arrangement.\n\nA garment scene can describe the present demonstration without becoming I have always recommended this. Where a genuine personal opinion is wanted, let the creator identify what they can truthfully say and confirm applicable commercial context.\n\nA refusal to state a particular experience does not automatically make the production defective. Scope and authenticity belong in the same discussion. This protects the brand too: an attractive performance should not be accepted as evidence for a factual claim the performer never made and the production agreement never required."
        ],
        [
          "metaMarketplace"
        ]
      ],
      [
        [
          "演练一次运动服拍摄与追加要求",
          "Rehearse a clothing shoot and an added request"
        ],
        [
          "假设品牌采购五张运动服展示图和一条适配说明，未包含教学或个人账号发布。拍摄当天又要求模特录制训练建议并承诺某种身体变化。此时不是简单补一句话，而是角色、主张和交付都改变了。案例没有真实模特或客户。\n\n负责人应回到原范围，确认新增工作是否适合、需要何种专业支持与事实审核，以及对方是否愿意。可以保留原制作，拒绝未经支持的主张，或重新定义合理任务。\n\n不能用已经到场或收到部分费用，推定所有新增内容都自动同意。后续广告用途也要单独核对。\n\n一份具体验收记录可以把五张图分别约定为整体服装展示、接缝细节、标签、已同意的日常动作和设备场景。这些是假设创意选择，不是统一姿势要求，更不是产品效果证据。拍摄前确认实际五项、画面范围和出镜人接受的条件。\n\n后来要求第六张或不同裁切时，说明属于原范围纠正还是额外工作。交接按批准图片记录版本与用途，不附带不必要的私人尺寸资料。媒体团队因此能找到正确素材，同时不把服装制作混成教学、身体数据或观众效果承诺。",
          "Suppose a brand purchases five garment images and one fit explanation, without instruction or personal-account publication. Onsite it adds training advice and a promised body change. That is not a simple extra sentence: role, claim and deliverable changed. This fictional case concerns no real model or client.\n\nReturn to scope and assess whether the addition is suitable, what professional support and fact review it requires and whether the person accepts. Keep the original production, decline an unsupported claim or redefine a reasonable assignment.\n\nAttendance or partial payment does not establish acceptance of every addition. Later advertising use needs its own scope check too. The useful record explains which original deliverables remain valid, which request was declined or revised and who owns the next decision. It does not classify a principled refusal of an unagreed health promise as failure to perform the agreed clothing shoot.\n\nFor a concrete acceptance note, the five agreed images might cover overall garment presentation, a seam detail, a label, an agreed everyday movement and an equipment-context scene. These are hypothetical creative choices, not mandatory poses or evidence of product efficacy. Identify the actual approved five before filming, including framing and any conditions the performer accepted.\n\nIf the buyer later asks for a sixth image or an altered crop, describe whether it is a correction within the original scope or additional work. The file handoff can associate each approved image with version and intended use, without attaching unnecessary personal sizing information. This lets the media team locate the right asset while keeping a clothing-production decision separate from professional instruction, private body data and claims about what the product will do for viewers. Record the accepted version so future operators who did not attend the shoot can understand the same limits."
        ],
        []
      ],
      [
        [
          "按事实与交付验收，不评价身体价值",
          "Accept against facts and delivery rather than body judgments"
        ],
        [
          "验收核对批准版本、服装与产品事实、约定画面、字幕和使用条件。不要把个人审美偏好改成事实错误，也不在合作结束后才加入未约定的身体标准。真实制作问题应具体说明，让接收人知道如何处理。\n\n如果需要补拍或新角度，按原因与原范围讨论；新广告主张可能需要新制作而非免费修图。后期也不应在未经确认时改变身体外观，使作品传达不真实效果。\n\n保留必要的反馈与批准记录，减少对出镜人的无关评论。专业验收应围绕可讨论的作品对象。",
          "Check approved version, garment and product facts, agreed framing, captions and use conditions. Do not turn personal taste into a factual defect or introduce an unagreed body standard after collaboration. Describe actual production issues so a receiver knows how to address them.\n\nDiscuss additional filming or angles according to cause and scope. A new advertising claim may need new production rather than free retouching. Do not alter appearance without appropriate confirmation in a way that implies an unreal product effect.\n\nRetain necessary feedback and approval while avoiding irrelevant personal commentary. Professional acceptance concerns a reviewable work object. A feedback note about a product label being unreadable is actionable in a way that an unexplained judgment about the person’s appearance is not; the distinction should remain clear when an agency consolidates comments."
        ],
        []
      ],
      [
        [
          "把费用、样品与后续责任写清",
          "Clarify fees, samples and follow-up responsibility"
        ],
        [
          "费用分别说明制作、账号发布、许可与额外版本；样品是借用还是赠送、如何归还，也应实际约定。不从关注数或外貌推导统一价格，也不将赠送产品自动当作发布义务。\n\n作品公开后，谁处理尺码咨询、订单与产品问题？模特或创作者只承担约定范围，不应猜客服政策或退款保证。品牌接收能力也影响整个合作是否准备好。\n\n期限结束、条件变化或需要修正时有明确联系路径，避免素材无限期停在可用库存里而没有任何复核。",
          "Separate production, publication, licensing and extra-version fees. Agree whether samples are loans or gifts and how returns work. Derive no universal price from scale or appearance, and treat a gift as neither automatic publication obligation nor a substitute for defined scope.\n\nWho handles sizing inquiries, orders and product questions after publication? The model or creator has agreed responsibilities rather than an obligation to guess support policy or refund guarantees. Brand receiving capacity affects readiness too.\n\nProvide a route for term expiry, changed conditions or correction so assets do not remain indefinitely in usable inventory without review. A production handoff should identify the person who can stop future use and the record needed to locate affected files, while leaving unrelated completed work and obligations accurately described."
        ],
        []
      ],
      [
        [
          "用明确任务形成尊重的合作",
          "Build a respectful collaboration through a clear task"
        ],
        [
          "最终交出角色、证据、场景、同意、主张、版本、费用与许可。让出镜人、创作者、品牌和媒体接收人都能知道自己负责什么。没有确认的资格与条件不应由照片补全。\n\n女性健身模特可以在达人营销中承担有价值的制作与表达角色，但应按实际能力与约定选择。对身体的刻板判断、未经支持的健康主张和模糊使用范围，都不能替代一份具体合作说明。\n\n让作品真实、人物边界清楚、品牌事实可核对，才能把拍摄转成负责任的内容资产。",
          "Hand over role, evidence, scene, consent, claims, version, fees and permission. Performer, creator, brand and media receiver should each understand their responsibility. A photograph cannot supply unverified credentials or conditions.\n\nA female fitness model can contribute valuable production and expression in creator marketing when selected for actual capability and scope. Body stereotypes, unsupported health claims and vague usage do not replace a concrete assignment.\n\nGenuine work, clear personal boundaries and reviewable product facts turn a shoot into a responsible content asset. The final handoff should let another colleague explain the intended use and limitations without making fresh assumptions about the person on camera or the results an audience might obtain."
        ],
        []
      ]
